UserModels:
query UserModels($id: ID!, $paid: PaidEnum, $limit: Int!, $cursor: String, $ordering: String, $search: String) {
  userModels(
    userId: $id
    paid: $paid
    limit: $limit
    cursor: $cursor
    ordering: $ordering
    query: $search
  ) {
    cursor
    items {
      ...Model
    }
  }
}
fragment Model on PrintType {
  id
  name
  slug
  ratingAvg
  likesCount
  liked
  datePublished
  dateFeatured
  firstPublish
  downloadCount
  mmu
  category {
    id
    path {
      id
      name
      nameEn
    }
  }
  modified
  image {
    ...SimpleImage
  }
  imagesCount
  nsfw
  aiGenerated
  politicalContent
  club: premium
  price
  priceBeforeSale
  eligibleForNomination
  user {
    ...AvatarUser
    isHiddenForMe
  }
  ...LatestContestResult
}
fragment LatestContestResult on PrintType {
  latestContestResult: latestCompetitionResult {
    ranking: placement
    competitionId
  }
}
fragment SimpleImage on PrintImageType {
  id
  filePath
  rotation
  imageHash
  imageWidth
  imageHeight
}
fragment AvatarUser on UserType {
  id
  handle
  verified
  dateVerified
  publicUsername
  avatarFilePath
  badgesProfileLevel {
    profileLevel
  }
}

