UploadModel:
mutation UploadModel($fileName: String!, $folder: String!, $unzip: Boolean!, $imageHash: String, $imageHeight: Int, $imageWidth: Int) {
  upload: printFileUpload2(
    fileName: $fileName
    folder: $folder
    unzip: $unzip
    imageHash: $imageHash
    imageHeight: $imageHeight
    imageWidth: $imageWidth
  ) {
    ok
